input.content:
package com.example.starter.domain;

/**
 * 运输段状态。
 */
public enum SegmentStatus {

    /** 段仍打开，尚未交接关闭。 */
    OPEN,

    /** 合格：序号连续、间隔不超限、无超限或连续超限未超过允许分钟数。 */
    CLEAR,

    /** 温度偏离：存在连续超限严格大于最大允许连续超限分钟数。 */
    EXCURSION,

    /** 证据不完整：缺号、采样间隔超限或覆盖序号范围前后缺读数。 */
    INCOMPLETE
}

package com.example.starter.web;

import org.springframework.http.HttpStatus;

/**
 * 业务请求无法处理（参数语义错误、缺号、时间倒退等），映射 HTTP 422。
 */
public class UnprocessableException extends RuntimeException {

    public UnprocessableException(String message) {
        super(message);
    }

    /**
     * @return 该异常对应的 HTTP 状态码
     */
    public HttpStatus status() {
        return HttpStatus.UNPROCESSABLE_ENTITY;
    }
}

package com.example.starter.web;

import org.springframework.http.HttpStatus;

/**
 * 请求目标不存在（货件不存在等），映射 HTTP 404。
 */
public class NotFoundException extends RuntimeException {

    public NotFoundException(String message) {
        super(message);
    }

    /**
     * @return 该异常对应的 HTTP 状态码
     */
    public HttpStatus status() {
        return HttpStatus.NOT_FOUND;
    }
}

package com.example.starter.web;

import org.springframework.http.HttpStatus;

/**
 * 状态或幂等冲突（序号重复改值、版本冲突、幂等键异参、已关闭段补写等），映射 HTTP 409。
 */
public class ConflictException extends RuntimeException {

    public ConflictException(String message) {
        super(message);
    }

    /**
     * @return 该异常对应的 HTTP 状态码
     */
    public HttpStatus status() {
        return HttpStatus.CONFLICT;
    }
}

